<script setup lang="ts">
import SoftSelect from '../components/SoftSelect.vue'
import { ref } from 'vue'
import { api, post, query, requestId, datetime } from '../lib/api'
import { isParent, selectedDate } from '../lib/state'
import { useResource, loadStudents, openDialog, studentOptions, label } from '../lib/ui'
import type { Fitness, Points } from '../lib/types'
import PageHeader from '../components/PageHeader.vue'
import AppIcon from '../components/AppIcon.vue'
import LoadState from '../components/LoadState.vue'
const tab=ref('fitness');const studentId=ref<string | number>('');const students=useResource(loadStudents)
const {data,loading,error,refresh}=useResource(async()=>{const [fitness,points]=await Promise.all([api<Fitness[]>(`/fitness${query({date:selectedDate.value,studentId:studentId.value})}`),api<Points[]>(`/points${query({studentId:studentId.value})}`)]);return {fitness,points}},[selectedDate,studentId])
async function fitness() {
  if(await openDialog({title:'批量体能打卡',description:'同一学生同一天同项目仅记录一次，并按机构规则奖励积分。',fields:[{key:'date',label:'打卡日期',type:'date',required:true},{key:'studentIds',label:'参与学生',type:'multi',required:true,options:studentOptions(students.data.value||[])},{key:'project',label:'体能项目',required:true,placeholder:'例如：跳绳、开合跳、平板支撑'},{key:'count',label:'完成次数',type:'number',min:0,required:true},{key:'duration',label:'运动时长（秒）',type:'number',min:0,required:true}],initial:{date:selectedDate.value,count:100,duration:60},submit:v=>post('/fitness/batch',v),success:'体能打卡已记录'}))refresh()
}
async function points() {
  const id=requestId()
  if(await openDialog({title:'调整成长积分',description:'单次 -100 至 100 分，不可透支。请填写清晰原因，积分变动将记入流水。',fields:[{key:'studentId',label:'学生',type:'select',required:true,options:studentOptions(students.data.value||[])},{key:'amount',label:'变动积分',type:'number',required:true,min:-100,max:100,hint:'奖励填写正数，扣减填写负数。'},{key:'reason',label:'调整原因',type:'textarea',required:true}],submit:v=>post('/points',{...v,requestId:id}),success:'积分已调整'}))refresh()
}
</script>
<template><PageHeader title="体能与积分" subtitle="身体向上，习惯向好，每一份努力都有回响。"><button v-if="!isParent" class="btn secondary" @click="points"><AppIcon name="Coins" :size="17" />积分调整</button><button v-if="!isParent" class="btn primary" @click="fitness"><AppIcon name="Dumbbell" :size="17" />体能打卡</button></PageHeader><div class="feature-strip"><div><span class="kpi-icon mint"><AppIcon name="Activity" :size="26" /></span><div><h3>动起来，成长更有力量</h3><p>完成运动，积累习惯，用正向反馈鼓励每一次坚持。</p></div></div><span class="feature-caption">HEALTHY BODY. HAPPY MIND.</span></div><section class="panel"><div class="filter-bar"><div class="tabs"><button :class="{active:tab==='fitness'}" @click="tab='fitness'">体能记录</button><button :class="{active:tab==='points'}" @click="tab='points'">积分流水</button></div><SoftSelect v-model="studentId" aria-label="体能积分学生" :options="[{value:'',label:'全部学生'}, ...(students.data.value || []).map(s => ({value:s.id,label:s.name}))]" /><span class="filter-count">{{ tab==='fitness'?selectedDate:'全部积分记录' }}</span><button class="icon-btn" aria-label="刷新体能积分" @click="refresh"><AppIcon name="RefreshCw" :size="17" /></button></div><LoadState :loading="loading" :error="error" :empty="!(tab==='fitness'?data?.fitness:data?.points)?.length" @retry="refresh"><div class="table-wrap"><table v-if="tab==='fitness'"><thead><tr><th>学生</th><th>运动项目</th><th>完成次数</th><th>时长</th><th>记录日期</th><th>确认状态</th></tr></thead><tbody><tr v-for="item in data?.fitness" :key="item.id"><td><strong>{{ item.studentName }}</strong><small v-if="item.campusName" class="block muted">{{ item.campusName }}</small></td><td><span class="subject-tag">{{ item.project }}</span></td><td class="numeric">{{ item.count }} 次</td><td class="numeric">{{ item.duration }} 秒</td><td>{{ item.date }}</td><td><span class="badge" :class="item.confirmed?'green':'amber'"><i></i>{{ item.confirmed?'已确认':'待确认' }}</span></td></tr></tbody></table><table v-else><thead><tr><th>学生</th><th>积分变动</th><th>变动后余额</th><th>类型</th><th>原因</th><th>发生时间</th></tr></thead><tbody><tr v-for="item in data?.points" :key="item.id"><td><strong>{{ item.studentName }}</strong><small v-if="item.campusName" class="block muted">{{ item.campusName }}</small></td><td class="numeric" :class="item.amount>0?'text-green':'text-danger'">{{ item.amount>0?'+':'' }}{{ item.amount }}</td><td class="numeric">{{ item.balance }}</td><td>{{ label(item.type) }}</td><td>{{ item.reason }}</td><td>{{ datetime(item.createdAt) }}</td></tr></tbody></table></div></LoadState></section></template>
